// Array.prototype.myMap
Array.prototype.myMap = function(cb) {
  const res = [];
  for (let i = 0; i < this.length; i++) {
    if (i in this) res.push(cb(this[i], i, this));
  }
  return res;
};

// Array.prototype.myFilter
Array.prototype.myFilter = function(cb) {
  const res = [];
  for (let i = 0; i < this.length; i++) {
    if (i in this && cb(this[i], i, this)) res.push(this[i]);
  }
  return res;
};

// Array.prototype.myReduce
Array.prototype.myReduce = function(cb, initVal) {
  let acc = initVal !== undefined ? initVal : this[0];
  let start = initVal !== undefined ? 0 : 1;
  for (let i = start; i < this.length; i++) {
    if (i in this) acc = cb(acc, this[i], i, this);
  }
  return acc;
};

// Function.prototype.myBind
Function.prototype.myBind = function(context, ...args1) {
  const fn = this;
  return function(...args2) {
    return fn.apply(context, [...args1, ...args2]);
  };
};

// Promise.myAll
Promise.myAll = function(promises) {
  return new Promise((resolve, reject) => {
    let results = [], completed = 0;
    if (!promises.length) return resolve([]);
    promises.forEach((p, idx) => {
      Promise.resolve(p).then(res => {
        results[idx] = res;
        completed++;
        if (completed === promises.length) resolve(results);
      }).catch(reject);
    });
  });
};
